Lemma exit_gen : forall i c k ps1, is_leaf i c k ps1 (CC.TOther RETPC) -> PB.exit_base_chk GT.NF RETPC c ps1 = true ->
  (forall E1 R1 E' R' (M1 M' : mem) model1, CC.At (hl_segs L) c E1 R1 M1 -> HAMB i E1 M1 model1 -> XI i E1 M1 -> PSI.SIM I eg i E1 M1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
     HAMB i E1 M' model1 -> env_agree GT.NF E0 E' ->
     exists (ps' : PML.pstate) (code : Z) (g' : PML.ls_state),
       PML.parser_at M' P ps' /\ PML.wf_ps ps' /\ PML.win_ok M' LBo ps' /\ PML.buf_bound ps' B /\ PML.ec_at M' E code /\ (code <> 0 -> PML.ps_more ps' = false) /\
       PML.ls_ok g' M' /\ (g' = g \/ g' = PML.LS2 /\ code <> 0) /\ CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps' /\
       (code <> 0 \/ PML.ps_more ps' = false \/ PMS.win_exhausted ps') /\
       (PML.ps_st ps = PML.ST_ACCEPT -> code = 0 /\ PML.ps_more ps' = false /\ PML.ps_done ps' = true) /\
       (PMS.win_exhausted ps -> code = 0 -> PML.ps_more ps' = true -> In (PML.ps_st ps) [PML.ST_NUMBER; PML.ST_CR] /\ ~ In (PML.ps_st ps') [PML.ST_NUMBER; PML.ST_CR]) /\
       (code = 0 -> PML.ws_ok ps') /\ (code = 0 -> PMX.enc_sync ps' eg) /\ PSI.WEXIT I ps' code M' eg) ->      (* [comment removed for export] *)
